param([Parameter(Mandatory)][string] $DisposableVolumeId,[Parameter(Mandatory)][string] $TestAccountSid)
# Plan only: deliberately contains no fill/quota/format execution path.
$ErrorActionPreference='Stop'
if($DisposableVolumeId -notmatch '^\\\\\?\\Volume\{[0-9a-fA-F-]+\}\\$') {throw 'Use a recorded guest volume GUID, never a drive letter.'}
if($TestAccountSid -notmatch '^S-1-5-21-[0-9-]+$') {throw 'Use the dedicated guest test account SID.'}
@{schema=1;status='PREPARED-NOT-EXECUTED';volume=$DisposableVolumeId;account=$TestAccountSid;ownerApprovalRequired=$true;trials=@('Full-volume: write non-sparse filler in 1 MiB chunks, Flush(true), record actual free bytes and native errors','Quota: approved guest-only fsutil quota track/enforce/modify; record and verify effective test SID','Metadata pressure: many small files/directories on dedicated NTFS; do not infer MFT exhaustion from a byte threshold','Run each credential/backup/restore operation near object, manifest, backup-root and root-staging allocation limits','Retain separate recovery disk and known filler manifest; delete only manifest-listed filler after evidence collection','Reopen current and all retained roots with historical credentials; compare ACK hash and sequence','Flush: injected errors are separate from real controller refusal; a full disk alone need not fail FlushFileBuffers');guards=@('Guest disposable VM identity checked','Volume is fixed NTFS, labelled SAFENOOK-DISPOSABLE, non-system/non-boot/no-pagefile','Volume disk unique ID matches operator approval','No host/shared/passthrough disk','No system quota changes; no automatic format, cleanup or repair')} | ConvertTo-Json -Depth 6
